declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require MIZ_ROOT.'/app/pages.php';if(!installed())redirect('install.php');$u=require_user();$error=null;$success=null;$recovery=null;
if($_SERVER['REQUEST_METHOD']==='POST')try{verify_csrf($_POST['_csrf']??null);rate_limit('account',client_ip().'|'.$u['id'],10);$record=one('SELECT * FROM '.table('users').' WHERE id=?',[$u['id']]);if(!password_verify((string)($_POST['current_password']??''),$record['password_hash']))fail(422,'PASSWORD','رمز فعلی درست نیست.');$next=validate_password($_POST['password']??null);if($next!==($_POST['password_repeat']??''))fail(422,'PASSWORD','تکرار رمز یکسان نیست.');[$recovery,$hash]=new_recovery();query('UPDATE '.table('users').' SET password_hash=?,recovery_hash=?,session_version=session_version+1 WHERE id=?',[password_digest($next),$hash,$u['id']]);$u['session_version']=(int)$u['session_version']+1;login_user($u);query('DELETE FROM '.table('room_presence').' WHERE user_id=?',[$u['id']]);$success='رمز تغییر کرد؛ نشست‌های دیگر بسته شدند. کد بازیابی تازه را ذخیره کن.';}catch(ApiError $e){$error=$e->getMessage();}catch(Throwable $e){error_log('Miz password failure '.$e->getCode());$error='تغییر رمز انجام نشد؛ دوباره امتحان کن.';}
page_start('امنیت حساب','حساب '. $u['display_name']);message($error);message($success,true);if($recovery)echo '<code class="recovery-code">'.e($recovery).'</code>';?><p dir="ltr"><?=e($u['email'])?></p><form method="post"><?php csrf_field();field('رمز فعلی','current_password','password','','current-password');field('رمز تازه','password','password','','new-password');field('تکرار رمز تازه','password_repeat','password','','new-password');?><button class="primary-button" type="submit">تغییر رمز و کد بازیابی</button></form><div class="account-links"><a href="<?=e(url())?>">برگشت به میز</a></div><?php page_end(); ?>
